function getStoredLanguage(): LanguageCode {
  if (typeof window === "undefined") return "EN";
  const value = window.localStorage.getItem(STORAGE_KEY);
  if (value && value in dictionary) return value as LanguageCode;
  return "EN";
}

export function useSiteLanguage() {
  const [language, setLanguageState] = useState<LanguageCode>("EN");

  useEffect(() => {
    const current = getStoredLanguage();
    setLanguageState(current);
    document.documentElement.lang = htmlLang[current];

    const handleLanguageEvent = (event: Event) => {
      const detail = (event as CustomEvent<LanguageCode>).detail;
      const next = detail && detail in dictionary ? detail : getStoredLanguage();
      setLanguageState(next);
      document.documentElement.lang = htmlLang[next];
    };

    const handleStorage = (event: StorageEvent) => {
      if (!event.key || event.key === STORAGE_KEY) {
        const next = getStoredLanguage();
        setLanguageState(next);
        document.documentElement.lang = htmlLang[next];
      }
    };

    window.addEventListener("everbond-language-change", handleLanguageEvent as EventListener);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener("everbond-language-change", handleLanguageEvent as EventListener);
      window.removeEventListener("storage", handleStorage);
    };
  }, []);

  const setLanguage = useCallback((next: LanguageCode) => {
    setLanguageState(next);
    if (typeof window !== "undefined") {
      window.localStorage.setItem(STORAGE_KEY, next);
      document.documentElement.lang = htmlLang[next];
      window.dispatchEvent(new CustomEvent("everbond-language-change", { detail: next }));
    }
  }, []);

  const t = useCallback((key: string) => {
    return dictionary[language][key] ?? dictionary.EN[key] ?? key;
  }, [language]);

  return { language, setLanguage, t };
}
